      const a=data.announcement,c=data.counts,h=data.handover;
      const handoverStatus={pending:'待继任者接受',accepted:'已完成',forced:'管理员兜底完成',cancelled:'已取消'};
      const people=p=>`${esc(p.name)} <small>${esc(p.employee_no)}</small>`;
