    const values=()=>{const raw=new FormData(form),fixed=seed.id&&seed.responsibility_scope_locked;return {...seed,title:raw.get('title'),summary:raw.get('summary'),body:raw.get('body'),category:fixed?seed.category:raw.get('category'),scope_kind:fixed?seed.scope_kind:raw.get('scope_kind'),attraction_ids:fixed?seed.attraction_ids:raw.get('scope_kind')==='circle'?raw.getAll('attraction_ids').map(Number):[],project_id:fixed?seed.project_id:raw.get('scope_kind')==='project'?Number(raw.get('project_id')):null,tiers:raw.getAll('tiers'),confirmation_level:Number(raw.get('confirmation_level')),training_required:Number(raw.get('confirmation_level'))===3&&form.elements.training_required.checked,trainer_scope:raw.get('trainer_scope')||'circle',trainer_ids:Number(raw.get('confirmation_level'))===3&&form.elements.training_required.checked?raw.getAll('trainer_ids').map(Number):[],effective_on:raw.get('effective_on'),due_on:raw.get('due_on')||null,expires_on:raw.get('expires_on')||null,attachments:attachments.map(({file_id,kind,caption})=>({file_id,kind,caption:caption||''})),change_summary:raw.get('change_summary')||''};};
